-- Roughly where the player is inside a dungeon, for the map's "You are here (approx.)" marker (UI/MapHere.lua).
--
-- Inside an instance the client gives an addon no map position (docs/COMPATIBILITY.md section 10), but it names the
-- area the player stands in: GetSubZoneText(), else GetMinimapZoneText(). Data/SubzoneData.lua (generated by
-- tools/gen_subzones.lua) places each named area of a dungeon on its recommended plan's floors, by ID, so any client
-- language matches:
--   * an AreaTable area (`a`): its name in the client's language from C_Map.GetAreaInfo(id);
--   * a WMO area (`w`): no game call names it by ID, so the data holds a hash (Subzones.Hash) of each name the client's
--     own table gives it, per client language (`h`, in the order of ns.SubzoneLocales); never the names.
-- A sub-zone that reads the same as the zone (GetZoneText) is the instance itself and places nothing. Every name read
-- from the game passes through Util.Plain (a secret one counts as none) and is trimmed, as the generator trims.
--
-- Matching is by instance, like Data/Spawns.lua: a player's own plan or a copy of a recommended one gets the same
-- anchors, floor i of the plan being the instance's i-th floor. The player must be inside that instance: the data's
-- instance map ID is GetInstanceInfo's eighth value.

local _, ns = ...
local Subzones = ns:NewModule("Subzones")
local Util = ns.Util

local TWO32 = 4294967296

-- XOR of a 32-bit value and a byte. WoW has the BitOp library (`bit`); plain Lua 5.1 (the generator, the tests)
-- does not, and gets the same answer from the low byte.
local function xorByte(h, byte)
	local bit = rawget(_G, "bit")
	if type(bit) == "table" and type(bit.bxor) == "function" then
		return bit.bxor(h, byte) % TWO32
	end
	local low = h % 256
	local out, place = 0, 1
	for _ = 1, 8 do
		local a, b = low % 2, byte % 2
		if a ~= b then
			out = out + place
		end
		low, byte, place = (low - a) / 2, (byte - b) / 2, place * 2
	end
	return h - h % 256 + out
end

-- 32-bit FNV-1a over the bytes of `text` (UTF-8 as the client gives it). The multiply by the FNV prime 16777619 is
-- split as h * 2^24 + h * 403: each part and their sum are exact in a double, so no bit operation is needed for it.
function Subzones.Hash(text)
	local h = 2166136261
	for i = 1, #text do
		h = xorByte(h, text:byte(i))
		h = (h * 16777216 % TWO32 + h * 403) % TWO32
	end
	return h
end

local function plainText(value)
	value = Util.Plain(value)
	return type(value) == "string" and value:match("^%s*(.-)%s*$") or nil
end

local function call(name, ...)
	local fn = rawget(_G, name)
	if type(fn) ~= "function" then
		return nil
	end
	local ok, value = pcall(fn, ...)
	return ok and plainText(value) or nil
end

-- The data of a plan's instance (by its canonical name, else its alias, as Data/Spawns.lua finds spawns), or nil.
function Subzones.For(plan)
	local data = ns.SubzoneData
	local name = type(data) == "table" and type(plan) == "table" and type(plan.instance) == "table"
		and ns.Instances.CanonicalName(plan)
	local key = type(name) == "string" and ns.GameFiles.Key(name)
	if not key then
		return nil
	end
	if data[key] then
		return data[key]
	end
	local spec = ns.GameFiles.INSTANCES and ns.GameFiles.INSTANCES[key]
	local alias = type(spec) == "table" and spec.alias
	return alias and data[alias] or nil
end

-- Where the player is as the client says it: { instanceID, zone, subzone, hash }; subzone nil when there is none,
-- when it reads the same as the zone, or when a value is secret. Asked on a zone change, not on every draw.
function Subzones.Where()
	local instanceID
	local fn = rawget(_G, "GetInstanceInfo")
	if type(fn) == "function" then
		local ok, _, kind, _, _, _, _, _, id = pcall(fn)
		kind, id = ok and Util.Plain(kind), ok and Util.Plain(id)
		if (kind == "party" or kind == "raid") and Util.IsInteger(id) then
			instanceID = id
		end
	end
	local zone = call("GetZoneText")
	local sub = call("GetSubZoneText")
	if not sub or sub == "" then
		sub = call("GetMinimapZoneText")
	end
	if sub == "" or sub == zone then
		sub = nil
	end
	return { instanceID = instanceID, zone = zone, subzone = sub, hash = sub and Subzones.Hash(sub) }
end

-- The position of the client's language in the data's hashes (English clients in Britain report enGB), found once;
-- false for a language the data has no names in.
local localeIndex

local function langIndex()
	if localeIndex == nil then
		local loc = call("GetLocale")
		loc = (loc == "enGB" or not loc) and "enUS" or loc
		localeIndex = false
		for i, l in ipairs(ns.SubzoneLocales or {}) do
			if l == loc then
				localeIndex = i
			end
		end
	end
	return localeIndex
end

-- AreaTable names by ID, kept once the client gives one (bounded by the areas in the data). No answer is not kept: the
-- client may not have loaded the name yet, so the next call asks again.
local areaNames = {}

local function areaName(id)
	if not areaNames[id] then
		local api = rawget(_G, "C_Map")
		local name
		if type(api) == "table" and type(api.GetAreaInfo) == "function" then
			local ok, value = pcall(api.GetAreaInfo, id)
			name = ok and plainText(value) or nil
		end
		areaNames[id] = name ~= "" and name or nil
	end
	return areaNames[id]
end

-- Does area `a` of the data read like `where` (Subzones.Where) in this client?
function Subzones.Names(a, where)
	if a.a and areaName(a.a) == where.subzone then
		return true
	end
	local i = a.h and langIndex()
	local h = i and a.h[i]
	if type(h) == "table" then
		for _, v in ipairs(h) do
			if v == where.hash then
				return true
			end
		end
		return false
	end
	return h == where.hash
end

-- The areas of `data` (Subzones.For) that `where` names (a name some areas share: all of them), or an empty list:
-- only inside that instance.
function Subzones.Find(data, where)
	local out = {}
	if type(data) ~= "table" or type(where) ~= "table" or not where.subzone or where.instanceID ~= data.iid then
		return out
	end
	for _, a in ipairs(data) do
		if Subzones.Names(a, where) then
			out[#out + 1] = a
		end
	end
	return out
end

-- The player's marker on floor `floor` of `plan`: { name = the sub-zone as shown, x, y } in plan space, or nil when
-- the player is not inside its instance, the sub-zone is unknown, or no area of that name has an anchor on that floor.
-- `where` defaults to Subzones.Where().
function Subzones.Here(plan, floor, where)
	where = where or Subzones.Where()
	for _, a in ipairs(Subzones.Find(Subzones.For(plan), where)) do
		local x, y = Subzones.Anchor(a, floor)
		if x then
			return { name = where.subzone, x = x, y = y }
		end
	end
	return nil
end

-- Where area `a` lies on floor `floor` of its plan: x, y in plan space, or nil.
function Subzones.Anchor(a, floor)
	for _, p in ipairs(a.at) do
		if p[1] == floor then
			return p[2], p[3]
		end
	end
	return nil
end

-- An area's key, as data-src/subzones names it and group members send it (Share/Rooms.lua): "a<AreaTable ID>" or
-- "w<WMOAreaTable ID>". IDs only, so it reads the same in every client language.
function Subzones.Key(a)
	return a.a and ("a" .. a.a) or ("w" .. a.w)
end

-- The area of `data` with key `key`, or nil.
function Subzones.Area(data, key)
	for _, a in ipairs(data) do
		if Subzones.Key(a) == key then
			return a
		end
	end
	return nil
end

-- The data of every plan of the instance with this instance map ID (GetInstanceInfo's eighth value), in the order of
-- their keys: several where plans share an instance (Scarlet Monastery's wings, Stratholme's halves, Blackrock Spire);
-- empty for one the data does not cover. A player with no plan open still has an area to tell the group.
function Subzones.ForInstance(iid)
	local keys = {}
	for key, data in pairs(type(ns.SubzoneData) == "table" and ns.SubzoneData or {}) do
		if type(data) == "table" and data.iid == iid then
			keys[#keys + 1] = key
		end
	end
	table.sort(keys)
	local out = {}
	for i, key in ipairs(keys) do
		out[i] = ns.SubzoneData[key]
	end
	return out
end

-- The hashes of area `a`'s name in this client's language, { [hash] = true }: empty when the client cannot name it.
-- Kept only when complete: an AreaTable name the client has not given yet is asked again next time.
local hashCache = setmetatable({}, { __mode = "k" })
local function nameHashes(a)
	local set = hashCache[a]
	if not set then
		set = {}
		local name = a.a and areaName(a.a)
		if name then
			set[Subzones.Hash(name)] = true
		end
		local i = a.h and langIndex()
		local h = i and a.h[i]
		for _, v in ipairs(type(h) == "table" and h or { h or nil }) do
			set[v] = true
		end
		if name or not a.a then
			hashCache[a] = set
		end
	end
	return set
end

local function sameName(a, b)
	if a == b then
		return true
	end
	local names = nameHashes(a)
	for h in pairs(nameHashes(b)) do
		if names[h] then
			return true
		end
	end
	return false
end

-- Where a member who sent area key `key` is drawn on floor `floor` of `data`: the area and x, y, or nil. The sender
-- cannot tell apart areas that share a name, so any of them counts: the first, in the data's order, with an anchor on
-- that floor, as the player's own marker is placed (Subzones.Here). A key from another plan of the same instance (the
-- sender sends the first match across them) counts for an area of this plan with the same name.
function Subzones.Place(data, key, floor)
	local sent = Subzones.Area(data, key)
	for _, other in ipairs(sent and {} or Subzones.ForInstance(data.iid)) do
		sent = sent or Subzones.Area(other, key)
	end
	if not sent then
		return nil
	end
	for _, a in ipairs(data) do
		if sameName(sent, a) then
			local x, y = Subzones.Anchor(a, floor)
			if x then
				return a, x, y
			end
		end
	end
	return nil
end

-- Forget the area names and the language asked (tests switch the client's language).
function Subzones.Reset()
	areaNames, localeIndex, hashCache = {}, nil, setmetatable({}, { __mode = "k" })
end
